-- Forward-only, dormant adoption. The sticky fence survives journal_v1.
ALTER TABLE hotel_work_queues ADD COLUMN persistent_fence INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS hotel_quarantine_adoptions (
 queue_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY,
 intake_stage CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 next_stage CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 request_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 acceptance_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 working_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 control_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 receipt_bytes LONGBLOB NOT NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS hotel_queue_write_permits (
 queue_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 session_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 old_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
 new_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
 receipt_stage CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
 receipt_index INTEGER NULL,
 receipt_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
 PRIMARY KEY(queue_id,session_id)
) ENGINE=InnoDB;
DROP TRIGGER IF EXISTS hotel_quarantine_queue_update;
DROP TRIGGER IF EXISTS hotel_quarantine_queue_delete;
DROP TRIGGER IF EXISTS hotel_quarantine_receipt_insert;
DROP TRIGGER IF EXISTS hotel_quarantine_receipt_update;
DROP TRIGGER IF EXISTS hotel_quarantine_receipt_delete;
CREATE TRIGGER hotel_quarantine_queue_update BEFORE UPDATE ON hotel_work_queues FOR EACH ROW SET NEW.queue_id=IF((OLD.write_protocol='quarantine_v1' OR OLD.persistent_fence=1 OR NEW.persistent_fence=1) AND NOT (((NEW.queue_id <=> OLD.queue_id) AND (NEW.project_key <=> OLD.project_key) AND (NEW.admin_id <=> OLD.admin_id) AND (NEW.oauth_connection_id <=> OLD.oauth_connection_id) AND (NEW.mode <=> OLD.mode) AND (NEW.batch_limit <=> OLD.batch_limit) AND (NEW.start_country <=> OLD.start_country) AND (NEW.initial_phase_counter <=> OLD.initial_phase_counter) AND (NEW.phase_counter <=> OLD.phase_counter) AND (NEW.baseline_sha256 <=> OLD.baseline_sha256) AND (NEW.plan_sha256 <=> OLD.plan_sha256) AND (NEW.stage_index <=> OLD.stage_index) AND (NEW.state <=> OLD.state) AND (NEW.claim_sha256 <=> OLD.claim_sha256) AND (NEW.current_run_id <=> OLD.current_run_id) AND (NEW.accepted_batches <=> OLD.accepted_batches) AND (NEW.write_protocol <=> OLD.write_protocol) AND (NEW.data_snapshot_sha256 <=> OLD.data_snapshot_sha256) AND (NEW.persistent_fence <=> OLD.persistent_fence)) OR (((NEW.queue_id <=> OLD.queue_id) AND (NEW.project_key <=> OLD.project_key) AND (NEW.admin_id <=> OLD.admin_id) AND (NEW.oauth_connection_id <=> OLD.oauth_connection_id) AND (NEW.mode <=> OLD.mode) AND (NEW.batch_limit <=> OLD.batch_limit) AND (NEW.start_country <=> OLD.start_country) AND (NEW.initial_phase_counter <=> OLD.initial_phase_counter) AND (NEW.baseline_sha256 <=> OLD.baseline_sha256) AND (NEW.plan_sha256 <=> OLD.plan_sha256) AND (NEW.write_protocol <=> OLD.write_protocol) AND (NEW.data_snapshot_sha256 <=> OLD.data_snapshot_sha256) AND (NEW.persistent_fence <=> OLD.persistent_fence)) AND EXISTS(SELECT 1 FROM hotel_quarantine_intake_permits p JOIN hotel_work_receipts r ON r.queue_id=p.queue_id AND r.stage_id=p.stage_id AND r.receipt_sha256=p.receipt_sha256 WHERE p.queue_id=OLD.queue_id AND p.session_id=CONNECTION_ID() AND p.stage_index=OLD.stage_index AND p.claim_sha256=OLD.claim_sha256 AND OLD.persistent_fence=0 AND OLD.state='claimed' AND OLD.current_run_id IS NULL AND OLD.mode='continuous' AND NEW.stage_index=OLD.stage_index+1 AND NEW.state='ready' AND NEW.claim_sha256 IS NULL AND NEW.current_run_id IS NULL AND NEW.accepted_batches=p.target_accepted AND p.target_accepted=OLD.accepted_batches+1 AND NEW.phase_counter=p.target_phase AND p.target_phase=1-OLD.phase_counter FOR UPDATE)) OR EXISTS(SELECT 1 FROM hotel_queue_write_permits p JOIN hotel_quarantine_adoptions a ON a.queue_id=p.queue_id WHERE p.queue_id=OLD.queue_id AND p.session_id=CONNECTION_ID() AND p.old_sha256=SHA2(CONCAT_WS(CHAR(31),COALESCE(CAST(OLD.queue_id AS CHAR),'~'),COALESCE(CAST(OLD.project_key AS CHAR),'~'),COALESCE(CAST(OLD.admin_id AS CHAR),'~'),COALESCE(CAST(OLD.oauth_connection_id AS CHAR),'~'),COALESCE(CAST(OLD.mode AS CHAR),'~'),COALESCE(CAST(OLD.batch_limit AS CHAR),'~'),COALESCE(CAST(OLD.start_country AS CHAR),'~'),COALESCE(CAST(OLD.initial_phase_counter AS CHAR),'~'),COALESCE(CAST(OLD.phase_counter AS CHAR),'~'),COALESCE(CAST(OLD.baseline_sha256 AS CHAR),'~'),COALESCE(CAST(OLD.plan_sha256 AS CHAR),'~'),COALESCE(CAST(OLD.stage_index AS CHAR),'~'),COALESCE(CAST(OLD.state AS CHAR),'~'),COALESCE(CAST(OLD.claim_sha256 AS CHAR),'~'),COALESCE(CAST(OLD.current_run_id AS CHAR),'~'),COALESCE(CAST(OLD.accepted_batches AS CHAR),'~'),COALESCE(CAST(OLD.write_protocol AS CHAR),'~'),COALESCE(CAST(OLD.data_snapshot_sha256 AS CHAR),'~'),COALESCE(CAST(OLD.persistent_fence AS CHAR),'~')),256) AND p.new_sha256=SHA2(CONCAT_WS(CHAR(31),COALESCE(CAST(NEW.queue_id AS CHAR),'~'),COALESCE(CAST(NEW.project_key AS CHAR),'~'),COALESCE(CAST(NEW.admin_id AS CHAR),'~'),COALESCE(CAST(NEW.oauth_connection_id AS CHAR),'~'),COALESCE(CAST(NEW.mode AS CHAR),'~'),COALESCE(CAST(NEW.batch_limit AS CHAR),'~'),COALESCE(CAST(NEW.start_country AS CHAR),'~'),COALESCE(CAST(NEW.initial_phase_counter AS CHAR),'~'),COALESCE(CAST(NEW.phase_counter AS CHAR),'~'),COALESCE(CAST(NEW.baseline_sha256 AS CHAR),'~'),COALESCE(CAST(NEW.plan_sha256 AS CHAR),'~'),COALESCE(CAST(NEW.stage_index AS CHAR),'~'),COALESCE(CAST(NEW.state AS CHAR),'~'),COALESCE(CAST(NEW.claim_sha256 AS CHAR),'~'),COALESCE(CAST(NEW.current_run_id AS CHAR),'~'),COALESCE(CAST(NEW.accepted_batches AS CHAR),'~'),COALESCE(CAST(NEW.write_protocol AS CHAR),'~'),COALESCE(CAST(NEW.data_snapshot_sha256 AS CHAR),'~'),COALESCE(CAST(NEW.persistent_fence AS CHAR),'~')),256) AND NEW.persistent_fence=1 AND NEW.write_protocol='journal_v1' FOR UPDATE)),(SELECT guard_id FROM hotel_legacy_quarantine_gate),NEW.queue_id);
CREATE TRIGGER hotel_quarantine_queue_delete BEFORE DELETE ON hotel_work_queues FOR EACH ROW UPDATE hotel_legacy_quarantine_gate SET guard_id=IF(OLD.write_protocol='quarantine_v1' OR OLD.persistent_fence=1,2,guard_id) WHERE guard_id=1;
CREATE TRIGGER hotel_quarantine_receipt_insert BEFORE INSERT ON hotel_work_receipts FOR EACH ROW SET NEW.queue_id=IF(EXISTS(SELECT 1 FROM hotel_work_queues WHERE queue_id=NEW.queue_id AND (write_protocol='quarantine_v1' OR persistent_fence=1) FOR UPDATE) AND NOT(EXISTS(SELECT 1 FROM hotel_quarantine_intake_permits p WHERE p.queue_id=NEW.queue_id AND p.session_id=CONNECTION_ID() AND p.stage_id=NEW.stage_id AND p.stage_index=NEW.stage_index AND p.receipt_sha256=NEW.receipt_sha256 AND p.receipt_sha256=SHA2(NEW.receipt_json,256) FOR UPDATE) OR EXISTS(SELECT 1 FROM hotel_queue_write_permits p WHERE p.queue_id=NEW.queue_id AND p.session_id=CONNECTION_ID() AND p.receipt_stage=NEW.stage_id AND p.receipt_index=NEW.stage_index AND p.receipt_sha256=NEW.receipt_sha256 AND p.receipt_sha256=SHA2(NEW.receipt_json,256) FOR UPDATE)),(SELECT guard_id FROM hotel_legacy_quarantine_gate),NEW.queue_id);
CREATE TRIGGER hotel_quarantine_receipt_update BEFORE UPDATE ON hotel_work_receipts FOR EACH ROW SET NEW.queue_id=IF(EXISTS(SELECT 1 FROM hotel_work_queues WHERE queue_id IN(OLD.queue_id,NEW.queue_id) AND (write_protocol='quarantine_v1' OR persistent_fence=1) FOR UPDATE),(SELECT guard_id FROM hotel_legacy_quarantine_gate),NEW.queue_id);
CREATE TRIGGER hotel_quarantine_receipt_delete BEFORE DELETE ON hotel_work_receipts FOR EACH ROW UPDATE hotel_legacy_quarantine_gate SET guard_id=IF(EXISTS(SELECT 1 FROM hotel_work_queues WHERE queue_id=OLD.queue_id AND (write_protocol='quarantine_v1' OR persistent_fence=1) FOR UPDATE),2,guard_id) WHERE guard_id=1;

